def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if os.name == 'nt':
        # Convert shebang to a valid Windows command
        if cmd and cmd[0].startswith('#!'):
            interpreter = cmd[0][2:].strip().split()[0]
            script = cmd[1]
            cmd = (interpreter, script) + cmd[2:]
    return cmd

