def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    from collections import defaultdict, OrderedDict

    def decorating_function(user_function):
        cache = OrderedDict()
        frequency = defaultdict(int)
        cache_get = cache.get
        wrapper_hit = _make_key_user_function_hit(typed)

        def wrapper(*args, **kwargs):
            key = wrapper_hit(user_function, args, kwargs)
            try:
                value = cache_get(key, missing)
            except TypeError:
                # More than maxsize keys being tracked, do not cache
                return user_function(*args, **kwargs)
            else:
                if value is missing:
                    value = user_function(*args, **kwargs)
                    if len(cache) >= maxsize:
                        # Discard the least frequently used key
                        min_freq = min(frequency.values())
                        for k, v in cache.items():
                            if frequency[k] == min_freq:
                                del cache[k]
                                del frequency[k]
                                break
                    cache[key] = value
                else:
                    # Move the key to the end to show that it was recently used
                    cache.move_to_end(key)
                frequency[key] += 1
                return value

        wrapper.cache_clear = cache.clear
        wrapper.cache_stats = lambda: (len(cache), maxsize)
        return wrapper

    return decorating_function

