def _make_key_typed(args, kwds, typed=False):
    key = args
    if kwds:
        sorted_items = sorted(kwds.items())
        key += tuple(type(v)) + (k,) + (v,) for k, v in sorted_items
    elif len(args) == 1 and isinstance(args[0], tuple):
        key = tuple(type(element) for element in args[0]) + args[0]
    return key

