@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    parts = []
    parts.append(f"Exception: {str(e)}")
    trace = []
    tb = e.__traceback__
    level = 0
    while tb and level < max_level:
        frame = tb.tb_frame
        code = frame.f_code
        trace.append({
            'filename': code.co_filename,
            'lineno': tb.tb_lineno,
            'name': code.co_name
        })
        tb = tb.tb_next
        level += 1

    for entry in trace[:max_path_level]:
        parts.append(f"  File \"{entry['filename']}\", line {entry['lineno']}, in {entry['name']}")

    return "\n".join(parts)

def extostr(cls, e, max_level=30, max_path_level=5):
    if max_level <= 0:
        return "Max level reached"
    exc_type, exc_value, tb = e.__class__, e, e.__traceback__
    path = []
    while tb is not None and len(path) < max_path_level:
        path.append(tb.tb_frame.f_code.co_filename + ":" + str(tb.tb_lineno))
        tb = tb.tb_next
    formatted_exception = f"{exc_type.__name__}: {exc_value}\nTraceback (most recent call last):\n"
    for p in path:
        formatted_exception += f"  File {p}\n"
    return formatted_exception

