def _legacy_mergeOrderings(orderings):
    def merge_two_orderings(ordering1, ordering2):
        # Create a dictionary to map each item to its position in ordering1
        pos_map = {item: idx for idx, item in enumerate(ordering1)}
        result = []
        i, j = 0, 0

        while i < len(ordering1) and j < len(ordering2):
            if ordering1[i] == ordering2[j]:
                result.append(ordering1[i])
                i += 1
                j += 1
            elif ordering2[j] in pos_map:
                # If the current item of ordering2 is in ordering1, advance i until we find it
                while i < len(ordering1) and ordering1[i] != ordering2[j]:
                    result.append(ordering1[i])
                    i += 1
                # Now ordering1[i] == ordering2[j], add it to result and move both pointers
                if i < len(ordering1):
                    result.append(ordering1[i])
                    i += 1
                    j += 1
            else:
                # If the current item of ordering2 is not in ordering1, add it to result
                result.append(ordering2[j])
                j += 1

        # Add remaining elements from ordering1
        result.extend(ordering1[i:])
        # Add remaining elements from ordering2
        result.extend(ordering2[j:])

        return result

    if not orderings:
        return []

    merged_ordering = orderings[0]
    for ordering in orderings[1:]:
        merged_ordering = merge_two_orderings(merged_ordering, ordering)

    return merged_ordering

def _legacy_mergeOrderings(orderings):
    graph = {}
    for ordering in orderings:
        for i in range(len(ordering) - 1):
            if ordering[i] not in graph:
                graph[ordering[i]] = set()
            graph[ordering[i]].add(ordering[i + 1])

    def dfs(node, visited, stack):
        visited.add(node)
        if node in graph:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    dfs(neighbor, visited, stack)
        stack.append(node)

    visited = set()
    stack = []
    for node in graph:
        if node not in visited:
            dfs(node, visited, stack)

    ordered_list = []
    reverse_map = {item: i for i, item in enumerate(stack[::-1])}
    orderings_flat = [item for sublist in orderings for item in sublist]
    unique_items = list(dict.fromkeys(orderings_flat))

    for item in unique_items:
        if item in reverse_map:
            ordered_list.append(item)
        else:
            ordered_list.append(item)

    return ordered_list

def _legacy_mergeOrderings(orderings):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    in_degree = defaultdict(int)

    for ordering in orderings:
        for i in range(len(ordering) - 1):
            u, v = ordering[i], ordering[i + 1]
            graph[u].append(v)
            in_degree[v] += 1

    queue = deque([node for node in set(graph) if in_degree[node] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Add any remaining nodes that are not part of any ordering
    for ordering in orderings:
        for item in reversed(ordering):
            if item not in result:
                result.append(item)

    return result

