def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Assuming self.SQLParams.in_style is defined and can be either 'named' or 'ordinal'
    if self.SQLParams.in_style == 'named':
        # Convert named parameters
        out_params = {k: v for k, v in params.items()}
        formatted_sql = sql
        for key in out_params.keys():
            formatted_sql = formatted_sql.replace(f":{key}", f"%({key})s")
    elif self.SQLParams.in_style == 'ordinal':
        # Convert ordinal parameters
        out_params = [v for v in params]
        formatted_sql = sql
        formatted_sql = formatted_sql.replace("%s", "{}").format(*("%%s",) * len(out_params))
    else:
        raise ValueError("Unsupported parameter style")

    return formatted_sql, out_params

def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if isinstance(params, dict):
			# Assuming named parameters
			out_params = {f":{key}": value for key, value in params.items()}
			formatted_sql = sql
			for old_param in params:
				new_param = f":{old_param}"
				formatted_sql = formatted_sql.replace(f":{old_param}", new_param)
		else:
			# Assuming positional parameters
			out_params = [f":{i+1}" for i in range(len(params))]
			formatted_sql = sql
			for i, _ in enumerate(params):
				formatted_sql = formatted_sql.replace(f"%s", f":{i+1}", 1)
		return formatted_sql, out_params

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Assuming self.SQLParams.in_style is defined and can be 'named' or 'ordinal'
    if self.SQLParams.in_style == 'named':
        # Convert :named style to %s style
        out_sql = sql
        out_params = []
        for param in params.values():
            out_sql = out_sql.replace(f":{list(params.keys())[out_params.count(param)]}", "%s")
            out_params.append(param)
    elif self.SQLParams.in_style == 'ordinal':
        # Convert %s style to %s style (no change needed)
        out_sql = sql
        out_params = list(params)
    else:
        raise ValueError("Unsupported parameter style")

    return out_sql, out_params

