def _extract_number_and_supplment_from_issue_element(issue):
    issue = issue.lower().replace(' ', '').replace('-', '')
    number = ''
    supplement = ''
    suppl_keywords = ['suppl', 'suppl.', 'supp', 'spe', 'spe.', 'spepr', 's', 'pr']

    for char in issue:
        if char.isdigit():
            number += char
        else:
            break

    remaining = issue[len(number):]
    for keyword in suppl_keywords:
        if keyword in remaining:
            supplement = keyword
            break

    return number, supplement

def _extract_number_and_supplment_from_issue_element(issue):
    issue = issue.lower()
    number = None
    suppl = None

    # Check for number
    if issue.startswith(('s', 'suppl', 'spe')):
        issue = issue[1:]
        number = issue.split()[0] if issue.split() else None
    else:
        number = issue.split()[0] if issue.split() else None

    # Check for suppl
    if 'suppl' in issue or 'spe' in issue:
        suppl = 'suppl'
    if 'pr' in issue:
        suppl += ' pr' if suppl else 'pr'

    # Extracting additional suppl info
    if number:
        issue = issue.replace(number, '').strip()
    suppl_info = issue.replace('suppl', '').replace('spe', '').strip()
    if suppl_info:
        suppl += ' ' + suppl_info

    return number, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    return ("  " * indent) + str(self) + ("\n" if debug else "")

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = '  ' * indent
    result = f"{indent_str}<{self.__class__.__name__}>\n"
    for attr, value in self.__dict__.items():
        if isinstance(value, list):
            result += f"{indent_str}  {attr}:\n"
            for item in value:
                if hasattr(item, 'pretty'):
                    result += item.pretty(indent + 2) + "\n"
                else:
                    result += f"{indent_str}    {item}\n"
        elif isinstance(value, dict):
            result += f"{indent_str}  {attr}:\n"
            for key, val in value.items():
                result += f"{indent_str}    {key}: {val}\n"
        elif hasattr(value, 'pretty'):
            result += f"{indent_str}  {attr}:\n"
            result += value.pretty(indent + 2) + "\n"
        else:
            result += f"{indent_str}  {attr}: {value}\n"
    return result.strip()

