def normalized(self):
    normalized_delta = relativedelta()
    for attr in self.__dict__:
        if isinstance(self.__dict__[attr], float):
            int_part = int(self.__dict__[attr])
            fraction_part = self.__dict__[attr] - int_part
            if attr in ['years', 'months']:
                next_attr = ['months', 'days'][['years', 'months'].index(attr)]
                normalized_delta.__dict__[attr] = int_part
                normalized_delta.__dict__[next_attr] = int(fraction_part * {'years': 12, 'months': 30}[attr])
            elif attr in ['days', 'hours', 'minutes', 'seconds', 'microseconds']:
                next_attr = ['hours', 'minutes', 'seconds', 'microseconds', None][['days', 'hours', 'minutes', 'seconds', 'microseconds'].index(attr)]
                normalized_delta.__dict__[attr] = int_part
                if next_attr:
                    normalized_delta.__dict__[next_attr] = int(fraction_part * {'days': 24, 'hours': 60, 'minutes': 60, 'seconds': 1000000}[attr])
        else:
            normalized_delta.__dict__[attr] = self.__dict__[attr]
    return normalized_delta

def normalized(self):
