def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import sys
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        pattern = r"(?<!\\)(?:\\\\)*'([^']*)'|\s+"
        return [token.replace("\\'", "'") for token in re.split(pattern, s) if token]

    elif platform == 0:  # Windows/CMD
        pattern = r'(["\'])(.*?)(?<!\\)\1|(\s+|\Z)'
        tokens = re.split(pattern, s)
        result = []
        i = 0
        while i < len(tokens):
            if tokens[i] in ('"', "'"):
                # Quoted argument
                if i + 2 < len(tokens):
                    result.append(tokens[i+1].replace('\\"', '"').replace("\\'", "'"))
                    i += 3
            else:
                # Unquoted argument or whitespace
                if tokens[i].strip():
                    result.append(tokens[i].replace('\\"', '"').replace("\\'", "'"))
                i += 1
        return result

    else:
        raise ValueError("Unsupported platform value. Use 'this', 0, or 1.")

