        return self._scale
    elif isinstance(other, (int, float)):
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Cannot rescale graph with unknown or zero scale.")
        rescale_factor = other / self._scale
        for i, point in enumerate(self._data):
            self._data[i] = point[:-1] + (point[-1] * rescale_factor,)
            if self._errors:
                self._errors[i] *= rescale_factor
        self._scale = other
    else:
        raise TypeError("Scaling factor must be a number.")

