def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []
    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}")

    for name in iface.names():
        if name not in dir(candidate):
            errors.append(f"Candidate does not define necessary attribute or method '{name}'")
        else:
            spec = iface.get(name)
            if spec and callable(spec):
                candidate_spec = inspect.signature(getattr(candidate, name))
                try:
                    candidate_spec.bind_partial(*spec.parameters.values())
                except TypeError as e:
                    errors.append(f"Method '{name}' has an incorrect signature: {e}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide the interface {iface}")

    required_methods = set(iface.names(False, True))
    candidate_methods = set(dir(candidate))

    missing_methods = required_methods - candidate_methods
    for method in missing_methods:
        errors.append(f"Missing method: {method}")

    for method_name in required_methods & candidate_methods:
        method = getattr(iface, method_name)
        candidate_method = getattr(candidate, method_name)
        if method.signature != inspect.signature(candidate_method):
            errors.append(f"Incorrect signature for method {method_name}: expected {method.signature}, got {inspect.signature(candidate_method)}")

    required_attributes = set(iface.names(True, False))
    candidate_attributes = {name for name, value in candidate.__dict__.items() if not callable(value)}

    missing_attributes = required_attributes - candidate_attributes
    for attr in missing_attributes:
        errors.append(f"Missing attribute: {attr}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("Multiple errors verifying candidate:\n" + "\n".join(errors))

    return True

