def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []
    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface.getName()}")

    required_methods = iface.names(all=True)
    candidate_methods = set(dir(candidate))
    for name in required_methods:
        attribute = iface.getAttribute(name, None)
        if attribute is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute: {name}")
            elif not isinstance(getattr(candidate, name), attribute.__class__):
                errors.append(f"Attribute {name} is not of the correct type")
        else:
            if name not in candidate_methods:
                errors.append(f"Missing method: {name}")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Attribute {name} is not callable")
                iface_method = iface.get(name)
                if iface_method and not _compatible_signature(method, iface_method):
                    errors.append(f"Incorrect signature for method: {name}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("Multiple errors:\n" + "\n".join(errors))
